namespace sv_0a49e576b0764340bbab6d3aee72bc32.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@namespace sv_0a49e576b0764340bbab6d3aee72bc32.Components.Pages.Apply
@using sv_0a49e576b0764340bbab6d3aee72bc32.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" CompletedSteps="completedSteps" OnStepClicked="GoToStep" />

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error-banner">@errorMessage</div>
    }

    @if (submitted)
    {
        <div class="confirmation">
            <h2>&#10003; Application Submitted!</h2>
            <p>Your application has been received. Your application ID is <strong>@applicationId</strong>.</p>
        </div>
    }
    else
    {
        @switch (currentStep)
        {
            case 0:
                @* Step 1: Personal Info *@
                <section class="step-content">
                    <h2>Personal Information</h2>
                    <div class="form-group">
                        <label>Full Name *</label>
                        <input type="text" @bind="fullName" />
                    </div>
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" @bind="email" />
                    </div>
                    <div class="form-group">
                        <label>Phone *</label>
                        <input type="tel" @bind="phone" />
                    </div>
                    <div class="form-group">
                        <label>Address *</label>
                        <input type="text" @bind="address" />
                    </div>
                    <div class="step-actions">
                        <button class="btn-primary" @onclick="NextFromPersonalInfo" disabled="@isValidating">
                            @(isValidating ? "Validating..." : "Next")
                        </button>
                    </div>
                </section>
                break;

            case 1:
                @* Step 2: Work History *@
                <section class="step-content">
                    <h2>Work History</h2>
                    @for (int i = 0; i < workEntries.Count; i++)
                    {
                        var idx = i;
                        <WorkEntryForm Entry="workEntries[idx]"
                                       Index="idx"
                                       CanRemove="workEntries.Count > 1"
                                       OnChanged="entry => UpdateWorkEntry(idx, entry)"
                                       OnRemove="() => RemoveWorkEntry(idx)" />
                    }
                    <button type="button" class="btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>
                    <div class="step-actions">
                        <button class="btn-secondary" @onclick="() => GoToStep(0)">Back</button>
                        <button class="btn-primary" @onclick="NextFromWorkHistory">Next</button>
                    </div>
                </section>
                break;

            case 2:
                @* Step 3: References *@
                <section class="step-content">
                    <h2>References</h2>
                    @for (int i = 0; i < references.Count; i++)
                    {
                        var idx = i;
                        <ReferenceForm Entry="references[idx]"
                                       Index="idx"
                                       CanRemove="references.Count > 2"
                                       OnChanged="entry => UpdateReference(idx, entry)"
                                       OnRemove="() => RemoveReference(idx)" />
                    }
                    @if (references.Count < 3)
                    {
                        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
                    }
                    <div class="step-actions">
                        <button class="btn-secondary" @onclick="() => GoToStep(1)">Back</button>
                        <button class="btn-primary" @onclick="NextFromReferences">Next</button>
                    </div>
                </section>
                break;

            case 3:
                @* Step 4: Cover Letter *@
                <section class="step-content">
                    <h2>Cover Letter</h2>
                    <div class="form-group">
                        <textarea rows="12" maxlength="2000" @bind="coverLetter"></textarea>
                        <span class="char-count">@coverLetter.Length / 2000 characters</span>
                    </div>
                    <div class="step-actions">
                        <button class="btn-secondary" @onclick="() => GoToStep(2)">Back</button>
                        <button class="btn-primary" @onclick="NextFromCoverLetter">Next</button>
                    </div>
                </section>
                break;

            case 4:
                @* Step 5: Review & Submit *@
                <section class="step-content">
                    <h2>Review & Submit</h2>

                    <div class="review-section">
                        <div class="review-header">
                            <h3>Personal Information</h3>
                            <button class="btn-link" @onclick="() => GoToStep(0)">Edit</button>
                        </div>
                        <dl>
                            <dt>Name</dt><dd>@fullName</dd>
                            <dt>Email</dt><dd>@email</dd>
                            <dt>Phone</dt><dd>@phone</dd>
                            <dt>Address</dt><dd>@address</dd>
                        </dl>
                    </div>

                    <div class="review-section">
                        <div class="review-header">
                            <h3>Work History</h3>
                            <button class="btn-link" @onclick="() => GoToStep(1)">Edit</button>
                        </div>
                        @foreach (var entry in workEntries)
                        {
                            <div class="review-entry">
                                <strong>@entry.Title</strong> at @entry.Company<br />
                                @entry.StartDate.ToString("MMM yyyy") &ndash;
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")<br />
                                @if (!string.IsNullOrWhiteSpace(entry.Description))
                                {
                                    <p>@entry.Description</p>
                                }
                            </div>
                        }
                    </div>

                    <div class="review-section">
                        <div class="review-header">
                            <h3>References</h3>
                            <button class="btn-link" @onclick="() => GoToStep(2)">Edit</button>
                        </div>
                        @foreach (var reference in references)
                        {
                            <div class="review-entry">
                                <strong>@reference.Name</strong> (@reference.Relationship)<br />
                                @reference.Email @(!string.IsNullOrWhiteSpace(reference.Phone) ? $"| {reference.Phone}" : "")
                            </div>
                        }
                    </div>

                    <div class="review-section">
                        <div class="review-header">
                            <h3>Cover Letter</h3>
                            <button class="btn-link" @onclick="() => GoToStep(3)">Edit</button>
                        </div>
                        <p class="cover-letter-preview">@coverLetter</p>
                    </div>

                    <div class="step-actions">
                        <button class="btn-secondary" @onclick="() => GoToStep(3)">Back</button>
                        <button class="btn-primary" @onclick="SubmitApplication" disabled="@isSubmitting">
                            @(isSubmitting ? "Submitting..." : "Submit Application")
                        </button>
                    </div>
                </section>
                break;
        }
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();
    private string errorMessage = string.Empty;
    private bool isValidating;
    private bool isSubmitting;
    private bool submitted;
    private int applicationId;

    // Step 1 state
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;

    // Step 2 state
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3 state
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 state
    private string coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        errorMessage = string.Empty;
        currentStep = step;
    }

    // Step 1 navigation
    private async Task NextFromPersonalInfo()
    {
        errorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email)
            || string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            errorMessage = "Please fill in all required fields.";
