toolArgs.file_text:
.apply-container {
    max-width: 720px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

/* Step Indicator */
.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    gap: 0.25rem;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    text-align: center;
    position: relative;
    padding: 0.5rem 0.25rem;
    border-radius: 0.5rem;
    transition: opacity 0.2s;
}

.step-item.dimmed {
    opacity: 0.4;
}

.step-item.completed {
    cursor: pointer;
    opacity: 0.85;
}

.step-item.completed:hover {
    opacity: 1;
}

.step-item.active .step-badge {
    background: #2563eb;
    color: white;
}

.step-item.completed .step-badge {
    background: #16a34a;
    color: white;
}

.step-badge {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    background: #e5e7eb;
    font-weight: 600;
    font-size: 0.875rem;
    margin-bottom: 0.25rem;
}

.step-label {
    font-size: 0.75rem;
    font-weight: 500;
}

/* Step Content */
.step-content {
    background: #f9fafb;
    border: 1px solid #e5e7eb;
    border-radius: 0.75rem;
    padding: 1.5rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1rem;
}

/* Forms */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    font-size: 0.875rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.25rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

.char-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

/* Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    padding: 1rem;
    margin-bottom: 1rem;
    background: white;
}

.work-entry-header,
.reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.work-entry-header h4,
.reference-header h4 {
    margin: 0;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    gap: 0.75rem;
}

.btn-primary {
    background: #2563eb;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 0.375rem;
    font-weight: 500;
    cursor: pointer;
    font-size: 0.95rem;
}

.btn-primary:hover:not(:disabled) {
    background: #1d4ed8;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-secondary {
    background: white;
    color: #374151;
    border: 1px solid #d1d5db;
    padding: 0.6rem 1.5rem;
    border-radius: 0.375rem;
    font-weight: 500;
    cursor: pointer;
    font-size: 0.95rem;
}

.btn-secondary:hover {
    background: #f3f4f6;
}

.btn-remove {
    background: none;
    border: none;
    color: #dc2626;
    cursor: pointer;
    font-size: 0.85rem;
    font-weight: 500;
}

.btn-link {
    background: none;
    border: none;
    color: #2563eb;
    cursor: pointer;
    font-weight: 500;
    font-size: 0.875rem;
    text-decoration: underline;
}

/* Review */
.review-section {
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    padding: 1rem;
    margin-bottom: 1rem;
    background: white;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #6b7280;
}

.review-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f3f4f6;
}

.review-entry:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    font-size: 0.9rem;
    color: #374151;
}

/* Error & Confirmation */
.error-banner {
    background: #fef2f2;
    border: 1px solid #fecaca;
    color: #dc2626;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.confirmation {
    text-align: center;
    padding: 3rem 1rem;
    background: #f0fdf4;
    border: 1px solid #bbf7d0;
    border-radius: 0.75rem;
}

.confirmation h2 {
    color: #16a34a;
}

